type PeerRow = { peer: any; lastMessage: any; unreadCount: number; settings: any };
type QueuedMessage = { id: string; content: string; replyToId?: number; createdAt: number };
const fallbackAvatar = "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=96&q=80";
function avatarUrlFor(user?: any) { return user?.avatarUrl || user?.avatar || user?.profilePhotoUrl || user?.photoUrl || user?.imageUrl || null; }
function Avatar({ user, size = "md", online = false }: { user?: any; size?: "sm" | "md" | "lg"; online?: boolean }) { const sizeClass = size === "lg" ? "h-24 w-24" : size === "sm" ? "h-9 w-9" : "h-11 w-11"; return <div className={`relative ${sizeClass} shrink-0`}><SafeImage src={avatarUrlFor(user)} fallbackName={displayName(user)} alt={displayName(user)} loading="lazy" decoding="async" className="h-full w-full rounded-full object-cover" /><span className={`absolute bottom-0 right-0 h-3.5 w-3.5 rounded-full border-2 border-card ${online ? "bg-emerald-500" : "bg-zinc-400"}`} /></div>; }
function displayName(user?: any, fallback = "Tanryugram user") { return user?.name || user?.username || fallback; }
function isOnline(user?: any) { if (!user?.lastSignedIn) return false; return Date.now() - new Date(user.lastSignedIn).getTime() < 5 * 60 * 1000; }
function relativeTime(value?: string | Date | null) { if (!value) return ""; const date = new Date(value).getTime(); const seconds = Math.max(0, Math.floor((Date.now() - date) / 1000)); if (seconds < 60) return "Just now"; if (seconds < 3600) return `${Math.floor(seconds / 60)}m`; if (seconds < 86400) return `${Math.floor(seconds / 3600)}h`; if (seconds < 172800) return "Yesterday"; return new Date(value).toLocaleDateString([], { month: "short", day: "numeric" }); }
function dateLabel(value: string | Date) { const date = new Date(value); const now = new Date(); const startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime(); const startDate = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime(); const days = Math.round((startToday - startDate) / 86400000); if (days === 0) return "Today"; if (days === 1) return "Yesterday"; if (days < 7) return date.toLocaleDateString([], { weekday: "long" }); return date.toLocaleDateString([], { month: "long", day: "numeric" }); }
function mediaFromContent(content: string) { const match = content.match(/^MEDIA:(.+)$/); return match?.[1] || null; }
function renderMentionText(content: string) { if (content.startsWith("__tanryugram_attachment__")) { try { return <GroupInlineAttachment attachment={JSON.parse(content.slice("__tanryugram_attachment__".length))} />; } catch { return <span>Shared attachment</span>; } } return content.split(/(@[\w.-]+)/g).map((part, index) => part.startsWith("@") ? <span key={`${part}-${index}`} className="font-semibold text-violet-500">{part}</span> : <span key={`${part}-${index}`}>{part}</span>); }
function blobToDataUrl(file: Blob) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); }); }
function formatBytes(bytes?: number | null) { if (!bytes) return ""; if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`; return `${(bytes / (1024 * 1024)).toFixed(1)} MB`; }
function formatAttachmentDuration(seconds?: number | null) { if (!seconds || seconds < 1) return "0:00"; return `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, "0")}`; }
function usePersistedQueue(peerId: number) { const key = `tanryugram:message-queue:${peerId}`; const [queue, setQueue] = useState<QueuedMessage[]>(() => { try { return JSON.parse(localStorage.getItem(key) || "[]") as QueuedMessage[]; } catch { return []; } }); useEffect(() => { localStorage.setItem(key, JSON.stringify(queue)); }, [key, queue]); return [queue, setQueue] as const; }

export function MessengerExperience({ onExit, initialPeer, onOpenProfile }: { onExit: () => void; initialPeer?: any | null; onOpenProfile?: (user: any) => void }) {
  const normalizedInitialPeer = normalizeMessengerPeer(initialPeer);
  const { user } = useAuth(); const [mode, setMode] = useState<"inbox" | "new" | "group-create" | "chat">(normalizedInitialPeer ? "chat" : "inbox"); const [seededPeer, setSeededPeer] = useState<any | null>(normalizedInitialPeer); const [activePeer, setActivePeer] = useState<any | null>(normalizedInitialPeer);
  useEffect(() => {
    if (normalizedInitialPeer?.id) {
      setSeededPeer(normalizedInitialPeer);
      setActivePeer(normalizedInitialPeer);
      setMode("chat");
    }
  }, [normalizedInitialPeer?.id]); const [seedCall, setSeedCall] = useState<{ id: number; type: "audio" | "video"; caller: boolean } | null>(null); const incomingQuery = trpc.messages.incomingCalls.useQuery(undefined, { enabled: Boolean(user), refetchInterval: CALL_POLL_INTERVALS.incoming, refetchOnWindowFocus: true }); const incomingUpdate = trpc.messages.updateCall.useMutation(); const notificationQuery = trpc.notifications.list.useQuery(undefined, { enabled: Boolean(user), refetchInterval: 4000 }); const markNotification = trpc.notifications.markRead.useMutation(); const incoming = incomingQuery.data?.[0]; const incomingCall = incoming?.call; const incomingCaller = incoming?.caller; const mentionNotification = notificationQuery.data?.find((row: any) => !row.notification.isRead && row.notification.content?.includes("mentioned you"));
  useEffect(() => { const onPopState = () => { if (mode !== "inbox") { setMode("inbox"); setActivePeer(null); setSeedCall(null); } else onExit(); }; window.addEventListener("popstate", onPopState); return () => window.removeEventListener("popstate", onPopState); }, [mode, onExit]);
  const openNew = () => { window.history.pushState({ tanryugramMessages: "new" }, "", window.location.href); setMode("new"); }; const openGroupCreate = () => { window.history.pushState({ tanryugramMessages: "group-create" }, "", window.location.href); setMode("group-create"); }; const openPeer = (peer: any) => { const normalizedPeer = normalizeMessengerPeer(peer); if (!normalizedPeer) { toast.error("This profile cannot start a conversation yet."); return; } if (mode === "inbox") window.history.pushState({ tanryugramMessages: "chat" }, "", window.location.href); setSeededPeer(normalizedPeer); setActivePeer(normalizedPeer); setSeedCall(null); setMode("chat"); }; const back = () => { if (mode !== "inbox") { setMode("inbox"); setActivePeer(null); setSeedCall(null); } else onExit(); };
  const acceptGlobalCall = async () => { if (!incomingCall || !incomingCaller) return; await incomingUpdate.mutateAsync({ callId: incomingCall.id, status: "accepted" }); setActivePeer(incomingCaller); setSeedCall({ id: incomingCall.id, type: incomingCall.callType, caller: false }); setMode("chat"); window.history.pushState({ tanryugramMessages: "chat" }, "", window.location.href); incomingQuery.refetch(); }; const declineGlobalCall = async () => { if (incomingCall) { await incomingUpdate.mutateAsync({ callId: incomingCall.id, status: "declined" }); incomingQuery.refetch(); } };
  return <div className="fixed inset-0 z-[80] flex min-h-0 flex-col bg-background text-foreground">{mentionNotification && <button onClick={() => { markNotification.mutate({ notificationId: mentionNotification.notification.id }); notificationQuery.refetch(); }} className="absolute right-4 top-4 z-[100] max-w-[min(360px,calc(100vw-2rem))] rounded-2xl border border-violet-300/40 bg-card px-4 py-3 text-left shadow-2xl"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-violet-500">New mention</p><p className="mt-1 text-xs font-semibold">{displayName(mentionNotification.actor)} mentioned you in a group</p><p className="mt-1 text-[10px] text-muted-foreground">Tap to dismiss</p></button>}{mode === "inbox" && <MessengerInboxView activePeerId={messengerPeerId(seededPeer)} onSelectConversation={openPeer} onNewMessage={openNew} onCreateGroup={openGroupCreate} onExit={onExit} onOpenProfile={onOpenProfile} />}{mode === "new" && <NewMessageView onBack={back} onSelect={openPeer} />}{mode === "group-create" && <CreateGroupView onBack={back} onCreated={openPeer} />}{mode === "chat" && activePeer && (activePeer.isGroup ? <GroupConversationSurface group={activePeer} onBack={back} /> : <AdvancedMessengerChat peer={activePeer} initialCall={seedCall || undefined} onBack={back} />)}{incomingCall && incomingCaller && (!activePeer || activePeer.id !== incomingCaller.id) && <IncomingCallScreen caller={incomingCaller} callType={incomingCall.callType} onAccept={acceptGlobalCall} onDecline={declineGlobalCall} />}</div>;
}

export function MessengerInboxView({ onSelectConversation, onNewMessage, onCreateGroup, onExit, activePeerId, onOpenProfile }: { onSelectConversation: (peer: any) => void; onNewMessage?: () => void; onCreateGroup?: () => void; onExit?: () => void; activePeerId?: number | null; onOpenProfile?: (user: any) => void }) {
  const { user } = useAuth(); const [search, setSearch] = useState(""); const [tab, setTab] = useState<"chats" | "requests" | "discover">("chats");
  const peersQuery = trpc.messages.peers.useQuery({ peerId: activePeerId || undefined }, { enabled: Boolean(user), refetchInterval: 3000 });
  const groupsQuery = trpc.messages.groups.useQuery(undefined, { enabled: Boolean(user), refetchInterval: 5000 });
  const requestsQuery = trpc.messages.requests.useQuery(undefined, { enabled: Boolean(user), refetchInterval: 3000 });
  const userSearchTerm = search.trim().replace(/^@/, "");
  const userSearchQuery = trpc.discovery.search.useQuery({ query: userSearchTerm }, { enabled: Boolean(user) && tab !== "discover" && userSearchTerm.length > 1 });
  const rows = (peersQuery.data ?? []) as PeerRow[]; const groups = (groupsQuery.data ?? []) as any[];
  const filtered = rows.filter((row) => `${row.peer?.name || ""} ${row.peer?.username || ""} ${row.lastMessage?.content || ""}`.toLowerCase().includes(search.toLowerCase())); const sorted = [...filtered.filter((row) => row.settings?.isPinned), ...filtered.filter((row) => !row.settings?.isPinned)]; const active = sorted.slice(0, 8);
  return <div className="flex min-h-0 flex-1 flex-col bg-background"><header className="flex items-center gap-3 border-b border-border/70 px-4 py-3 sm:px-8 sm:py-4"><button onClick={onExit} aria-label="Close messages" className="rounded-full p-2 hover:bg-muted"><ArrowLeft className="h-5 w-5" /></button><div className="min-w-0 flex-1"><p className="text-xl font-bold tracking-tight">Messenger</p><p className="text-[11px] text-muted-foreground">Tanryugram conversations</p></div><div className="flex items-center gap-2"><button onClick={onCreateGroup} className="flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2 text-xs font-semibold hover:bg-muted"><Users className="h-4 w-4" /><span className="hidden sm:inline">Create group</span></button><button onClick={onNewMessage} className="flex items-center gap-2 rounded-xl bg-foreground px-3 py-2 text-xs font-semibold text-background"><span className="text-base leading-none">+</span><span className="hidden sm:inline">New message</span></button></div></header><div className="mx-auto flex min-h-0 w-full max-w-6xl flex-1 flex-col overflow-hidden sm:p-5 lg:flex-row lg:gap-5"><aside className="flex min-h-0 w-full flex-col border-b border-border/70 bg-card lg:w-[390px] lg:rounded-3xl lg:border lg:shadow-sm"><div className="border-b border-border/70 p-4 sm:p-5"><div className="flex items-center justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-violet-500">Inbox</p><h1 className="mt-1 text-2xl font-bold">Your chats</h1></div><div className="flex gap-1 rounded-xl bg-muted p-1"><button onClick={() => setTab("chats")} className={`rounded-lg px-2 py-1.5 text-[10px] font-semibold ${tab === "chats" ? "bg-card shadow-sm" : "text-muted-foreground"}`}>Chats</button><button onClick={() => setTab("requests")} className={`rounded-lg px-2 py-1.5 text-[10px] font-semibold ${tab === "requests" ? "bg-card shadow-sm" : "text-muted-foreground"}`}>Requests</button><button onClick={() => setTab("discover")} className={`rounded-lg px-2 py-1.5 text-[10px] font-semibold ${tab === "discover" ? "bg-card shadow-sm" : "text-muted-foreground"}`}>Discover</button></div></div><div className="relative mt-4"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={tab === "discover" ? "Search public groups" : "Search people or conversations"} className="h-11 w-full rounded-2xl bg-muted pl-10 pr-3 text-sm outline-none" />{tab !== "discover" && search.trim().length > 1 && <div className="absolute left-0 right-0 top-12 z-20 max-h-72 overflow-y-auto rounded-2xl border border-border bg-card p-1.5 shadow-xl">{(userSearchQuery.data?.users ?? []).slice(0, 8).map((person: any) => <MessengerSearchResult key={person.id} person={person} onSelect={(peer) => { setSearch(""); onSelectConversation(peer); }} />)}{!userSearchQuery.isLoading && !(userSearchQuery.data?.users ?? []).length && <p className="p-4 text-center text-xs text-muted-foreground">No users found. Try a name or @username.</p>}</div>}</div></div>{tab === "chats" && <><div className="border-b border-border/70 p-4"><div className="mb-3 flex items-center justify-between"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-violet-500">Active Now</p><span className="text-[10px] text-muted-foreground">{active.length} people</span></div><div className="flex gap-3 overflow-x-auto pb-1 [scrollbar-width:none]">{active.map((row) => <button key={`active-${row.peer.id}`} onClick={() => onSelectConversation(row.peer)} className="flex w-14 shrink-0 flex-col items-center gap-1.5"><Avatar user={row.peer} size="md" online={isOnline(row.peer)} /><span className="w-14 truncate text-[10px] font-medium">{displayName(row.peer)}</span></button>)}</div></div><div className="min-h-0 flex-1 overflow-y-auto p-2">{groups.map((group) => <GroupRow key={`group-${group.id}`} group={group} onOpen={() => onSelectConversation({ ...group, isGroup: true })} />)}{sorted.map((row) => <ConversationRow key={row.peer.id} row={row} selected={activePeerId === row.peer.id} onOpen={() => onSelectConversation(row.peer)} onOpenProfile={onOpenProfile} />)}{!sorted.length && !groups.length && <div className="p-6 text-center text-xs text-muted-foreground">No conversations found.</div>}</div></>}{tab === "requests" && <div className="min-h-0 flex-1 overflow-y-auto p-2">{(requestsQuery.data ?? []).filter((row: any) => `${row.peer?.name || ""} ${row.peer?.username || ""} ${row.lastMessage?.content || ""}`.toLowerCase().includes(search.toLowerCase())).map((row: any) => <button key={row.peer.id} onClick={() => onSelectConversation(row.peer)} className="flex w-full items-center gap-3 rounded-2xl p-3 text-left hover:bg-muted/70"><Avatar user={row.peer} online={isOnline(row.peer)} /><span className="min-w-0 flex-1"><b className="block truncate text-sm">{displayName(row.peer)}</b><span className="block truncate text-xs text-muted-foreground">{row.lastMessage?.content || "New message request"}</span></span>{row.unreadCount > 0 && <span className="rounded-full bg-violet-500 px-2 py-1 text-[10px] font-bold text-white">{row.unreadCount}</span>}</button>)}{!(requestsQuery.data ?? []).length && <div className="m-3 rounded-2xl border border-dashed border-border p-5 text-center"><Users className="mx-auto h-5 w-5 text-violet-500" /><p className="mt-2 text-sm font-semibold">No message requests</p><p className="mt-1 text-xs text-muted-foreground">New conversations from people outside your circle will appear here.</p></div>}</div>}{tab === "discover" && <GroupDiscoveryPanel query={search} memberGroupIds={groups.map((group) => group.id)} onOpen={onSelectConversation} onJoined={() => groupsQuery.refetch()} />}</aside><section className="hidden min-h-0 flex-1 items-center justify-center rounded-3xl border border-border/70 bg-card p-10 text-center shadow-sm lg:flex"><div className="max-w-sm"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl bg-violet-500/10 text-violet-500"><Users className="h-7 w-7" /></div><h2 className="mt-5 text-2xl font-bold">Find your community</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Create a private room or discover public communities around you.</p><button onClick={onCreateGroup} className="mt-5 rounded-2xl bg-foreground px-4 py-3 text-xs font-semibold text-background">Create a group</button></div></section></div></div>;
}

function GroupDiscoveryPanel({ query, memberGroupIds, onOpen, onJoined }: { query: string; memberGroupIds: number[]; onOpen: (group: any) => void; onJoined: () => void }) {
  const discovery = trpc.messages.discoverGroups.useQuery({ query }, { refetchInterval: 4000 }); const join = trpc.messages.joinGroup.useMutation({ onSuccess: (result, input) => { onJoined(); const row = (discovery.data ?? []).find((item: any) => item.group.id === input.groupId); if ((result.status === "joined" || result.status === "member") && row) { onOpen({ ...row.group, isGroup: true }); } else if (result.status === "requested") { toast.success("Join request sent"); } }, onError: (error) => toast.error("Could not join group", { description: error.message }) });
  return <div className="min-h-0 flex-1 overflow-y-auto p-3"><p className="mb-3 px-2 text-[10px] font-bold uppercase tracking-[0.18em] text-violet-500">Public communities</p>{(discovery.data ?? []).map((row: any) => { const isMember = memberGroupIds.includes(row.group.id); return <div key={row.group.id} className="mb-2 rounded-2xl border border-border/70 p-3"><div className="flex gap-3"><div className="flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-2xl bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white">{row.group.avatarUrl ? <img src={row.group.avatarUrl} alt="" className="h-full w-full object-cover" /> : <Users className="h-5 w-5" />}</div><div className="min-w-0 flex-1"><b className="block truncate text-sm">{row.group.name}</b><p className="mt-0.5 text-[11px] text-muted-foreground">{row.memberCount} members · {isMember ? "You’re a member" : row.group.joinMode === "open" ? "Open to join" : "Request to join"}</p><p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{row.group.description || "A Tanryugram community."}</p></div></div><button onClick={() => isMember ? onOpen({ ...row.group, isGroup: true }) : join.mutate({ groupId: row.group.id })} disabled={!isMember && join.isPending} className="mt-3 w-full rounded-xl bg-violet-500/10 py-2 text-xs font-semibold text-violet-600 hover:bg-violet-500/15">{isMember ? "Open group" : row.group.joinMode === "open" ? "Join group" : "Request to join"}</button></div>; })}{!discovery.isLoading && !(discovery.data ?? []).length && <div className="rounded-2xl border border-dashed border-border p-6 text-center text-xs text-muted-foreground">No public groups match this search.</div>}</div>;
}

function ConversationRow({ row, selected, onOpen, onOpenProfile }: { row: PeerRow; selected: boolean; onOpen: () => void; onOpenProfile?: (user: any) => void }) { const updateSettings = trpc.messages.settingsUpdate.useMutation(); const [menu, setMenu] = useState(false); const peer = row.peer; const nickname = row.settings?.nickname || ""; const label = nickname || displayName(peer); return <div className={`relative flex items-center gap-3 rounded-2xl p-3 transition ${selected ? "bg-violet-500/12" : "hover:bg-muted/70"}`}><button onClick={onOpen} className="flex min-w-0 flex-1 items-center gap-3 text-left"><span role="button" tabIndex={0} title={`Open ${label} profile`} onClick={(event) => { event.stopPropagation(); onOpenProfile?.(peer); }} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); event.stopPropagation(); onOpenProfile?.(peer); } }} className="cursor-pointer rounded-full outline-none ring-violet-400 focus:ring-2"><Avatar user={peer} online={isOnline(peer)} /></span><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><b className="truncate text-sm">{label}</b>{nickname && <span className="rounded-full bg-violet-500/10 px-1.5 py-0.5 text-[9px] text-violet-600">Nickname</span>}{row.settings?.isPinned && <Pin className="h-3 w-3 shrink-0 text-violet-500" />}</div><div className="mt-0.5 flex items-center gap-2"><p className="min-w-0 flex-1 truncate text-xs text-muted-foreground">{row.lastMessage?.content?.startsWith("MEDIA:") ? "Photo" : row.lastMessage?.content || "Start a conversation"}</p>{row.lastMessage?.createdAt && <span className="shrink-0 text-[10px] text-muted-foreground">{relativeTime(row.lastMessage.createdAt)}</span>}</div></div>{row.unreadCount > 0 && <span className="inline-flex h-5 min-w-5 items-center justify-center rounded-full bg-violet-500 px-1.5 text-[10px] font-bold text-white">{row.unreadCount}</span>}</button><button onClick={() => setMenu((value) => !value)} aria-label="Conversation actions" className="rounded-full p-2 text-muted-foreground hover:bg-muted"><MoreHorizontal className="h-4 w-4" /></button>{menu && <div className="absolute right-3 top-12 z-10 w-44 rounded-2xl border border-border bg-card p-1.5 shadow-xl"><button onClick={() => { const next = window.prompt("Set a private nickname for this account", nickname); if (next !== null) updateSettings.mutate({ peerId: peer.id, nickname: next.trim() || null }); setMenu(false); }} className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-xs hover:bg-muted">Rename nickname</button><button onClick={() => { updateSettings.mutate({ peerId: peer.id, isPinned: !row.settings?.isPinned }); setMenu(false); }} className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-xs hover:bg-muted"><Pin className="h-3.5 w-3.5" />{row.settings?.isPinned ? "Unpin" : "Pin"}</button><button onClick={() => { updateSettings.mutate({ peerId: peer.id, isArchived: true }); setMenu(false); }} className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-xs hover:bg-muted"><Archive className="h-3.5 w-3.5" />Archive</button><button onClick={() => { updateSettings.mutate({ peerId: peer.id, isMuted: !row.settings?.isMuted }); setMenu(false); }} className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-xs hover:bg-muted"><BellOff className="h-3.5 w-3.5" />{row.settings?.isMuted ? "Unmute" : "Mute"}</button></div>}</div>; }
function GroupRow({ group, onOpen }: { group: any; onOpen: () => void }) { return <button onClick={onOpen} className="flex w-full items-center gap-3 rounded-2xl p-3 text-left transition hover:bg-muted/70"><div className="flex h-11 w-11 shrink-0 items-center justify-center overflow-hidden rounded-full bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white">{group.avatarUrl ? <SafeImage src={group.avatarUrl} fallbackName={group.name} alt={group.name} loading="lazy" decoding="async" className="h-full w-full object-cover" /> : <Users className="h-5 w-5" />}</div><div className="min-w-0 flex-1"><b className="block truncate text-sm">{group.name}</b><p className="mt-0.5 truncate text-xs text-muted-foreground">Group chat · Tap to open</p></div><ChevronDown className="h-4 w-4 -rotate-90 text-muted-foreground" /></button>; }
function CreateGroupView({ onBack, onCreated }: { onBack: () => void; onCreated: (group: any) => void }) {
  const { user } = useAuth(); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [visibility, setVisibility] = useState<"public" | "private">("private"); const [joinMode, setJoinMode] = useState<"open" | "approval" | "invite">("invite"); const [postingMode, setPostingMode] = useState<"all" | "admins">("all"); const [photo, setPhoto] = useState<File | null>(null); const [query, setQuery] = useState(""); const [members, setMembers] = useState<any[]>([]);
  const results = trpc.discovery.search.useQuery({ query }, { enabled: query.trim().length > 1 }); const upload = trpc.media.uploadBase64.useMutation();
  const createGroup = trpc.messages.createGroup.useMutation({ onSuccess: (groupId) => { if (!groupId) { toast.error("Could not create group"); return; } onCreated({ id: Number(groupId), name: name.trim(), description, visibility, joinMode, postingMode, creatorId: user?.id, isGroup: true }); toast.success("Group created"); }, onError: (error) => toast.error("Could not create group", { description: error.message }) });
  const addMember = (person: any) => { if (person.id === user?.id || members.some((member) => member.id === person.id)) return; setMembers((selected) => [...selected, person]); setQuery(""); }; const removeMember = (id: number) => setMembers((selected) => selected.filter((member) => member.id !== id));
  const create = async () => { const groupName = name.trim(); if (!groupName) { toast.error("Add a group name"); return; } let avatarUrl: string | undefined; try { if (photo) { const data = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(photo); }); const uploaded = await upload.mutateAsync({ fileName: photo.name, base64Data: data, contentType: photo.type || "image/jpeg" }); avatarUrl = uploaded.url; } createGroup.mutate({ name: groupName, description: description.trim() || undefined, avatarUrl, visibility, joinMode: visibility === "public" ? joinMode : "invite", postingMode, memberIds: members.map((member) => member.id) }); } catch (error: any) { toast.error("Could not upload group photo", { description: error?.message }); } };
  const selectable = (results.data?.users ?? []).filter((person: any) => person.id !== user?.id && !members.some((member) => member.id === person.id));
  return <div className="flex min-h-0 flex-1 flex-col bg-background"><header className="flex items-center gap-3 border-b border-border/70 px-4 py-3 sm:px-8 sm:py-4"><button onClick={onBack} aria-label="Back to inbox" className="rounded-full p-2 hover:bg-muted"><ArrowLeft className="h-5 w-5" /></button><div><p className="text-xl font-bold">Create group</p><p className="text-[11px] text-muted-foreground">Shape a shared space for your people.</p></div></header><main className="mx-auto w-full max-w-2xl flex-1 overflow-y-auto p-4 sm:p-8"><section className="rounded-3xl border border-border/70 bg-card p-5 shadow-sm sm:p-7"><div className="flex items-start gap-4"><label className="flex h-16 w-16 shrink-0 cursor-pointer items-center justify-center overflow-hidden rounded-2xl bg-gradient-to-br from-violet-500 to-fuchsia-500 text-white"><input type="file" accept="image/*" className="hidden" onChange={(event) => setPhoto(event.target.files?.[0] || null)} />{photo ? <img src={URL.createObjectURL(photo)} alt="Group preview" className="h-full w-full object-cover" /> : <Users className="h-7 w-7" />}</label><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-violet-500">New community</p><h1 className="mt-1 text-2xl font-bold">Bring people together</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">Add an optional group photo, choose a visibility model, then invite your first members.</p></div></div><label className="mt-7 block"><span className="mb-2 block text-xs font-semibold">Group name</span><input value={name} onChange={(event) => setName(event.target.value)} maxLength={80} placeholder="e.g. Weekend creative crew" className="h-12 w-full rounded-2xl border border-border bg-background px-4 text-sm outline-none transition focus:border-violet-400" /></label><label className="mt-4 block"><span className="mb-2 block text-xs font-semibold">Description <span className="font-normal text-muted-foreground">(optional)</span></span><textarea value={description} onChange={(event) => setDescription(event.target.value)} maxLength={2000} placeholder="What is this group for?" className="min-h-24 w-full resize-y rounded-2xl border border-border bg-background p-4 text-sm outline-none focus:border-violet-400" /></label><div className="mt-4 grid gap-3 sm:grid-cols-3"><label className="text-xs font-semibold">Visibility<select value={visibility} onChange={(event) => setVisibility(event.target.value as "public" | "private")} className="mt-2 h-10 w-full rounded-xl bg-muted px-3 text-xs outline-none"><option value="private">Private</option><option value="public">Public</option></select></label><label className="text-xs font-semibold">Joining<select value={joinMode} disabled={visibility === "private"} onChange={(event) => setJoinMode(event.target.value as "open" | "approval" | "invite")} className="mt-2 h-10 w-full rounded-xl bg-muted px-3 text-xs outline-none disabled:opacity-50"><option value="open">Open</option><option value="approval">Approval</option><option value="invite">Invite only</option></select></label><label className="text-xs font-semibold">Who can post<select value={postingMode} onChange={(event) => setPostingMode(event.target.value as "all" | "admins")} className="mt-2 h-10 w-full rounded-xl bg-muted px-3 text-xs outline-none"><option value="all">All members</option><option value="admins">Admins only</option></select></label></div><div className="mt-6"><div className="flex items-center justify-between"><span className="text-xs font-semibold">People <span className="font-normal text-muted-foreground">(optional for public groups)</span></span><span className="text-[11px] text-muted-foreground">{members.length + 1} members including you</span></div><div className="relative mt-2"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search people by name or username" className="h-12 w-full rounded-2xl bg-muted pl-10 pr-4 text-sm outline-none" /></div>{members.length > 0 && <div className="mt-3 flex flex-wrap gap-2"><div className="flex items-center gap-2 rounded-full bg-violet-500/10 py-1.5 pl-2 pr-3 text-xs font-semibold text-violet-600"><Avatar user={user} size="sm" online /><span>You · Admin</span></div>{members.map((member) => <button key={member.id} onClick={() => removeMember(member.id)} className="flex items-center gap-2 rounded-full bg-muted py-1.5 pl-2 pr-3 text-xs font-medium hover:bg-rose-500/10 hover:text-rose-600"><Avatar user={member} size="sm" online={isOnline(member)} /><span>{displayName(member)}</span><X className="h-3.5 w-3.5" /></button>)}</div>}{query.trim().length > 1 && <div className="mt-3 max-h-64 overflow-y-auto rounded-2xl border border-border p-1.5">{selectable.map((person: any) => <button key={person.id} onClick={() => addMember(person)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left hover:bg-muted"><Avatar user={person} online={isOnline(person)} /><span className="min-w-0 flex-1"><b className="block truncate text-sm">{displayName(person)}</b><span className="block truncate text-xs text-muted-foreground">@{person.username || person.email || "user"}</span></span><span className="rounded-full bg-violet-500/10 px-2.5 py-1 text-[10px] font-semibold text-violet-600">Add</span></button>)}{!selectable.length && !results.isLoading && <p className="p-5 text-center text-xs text-muted-foreground">No additional people found.</p>}</div>}</div><button disabled={createGroup.isPending || upload.isPending || !name.trim()} onClick={() => void create()} className="mt-7 flex w-full items-center justify-center gap-2 rounded-2xl bg-foreground py-3.5 text-sm font-semibold text-background transition active:scale-[.98] disabled:opacity-40"><Users className="h-4 w-4" />{createGroup.isPending || upload.isPending ? "Creating group…" : `Create group · ${members.length + 1} members`}</button></section></main></div>;
}

function NewMessageView({ onBack, onSelect }: { onBack: () => void; onSelect: (peer: any) => void }) { const [query, setQuery] = useState(""); const results = trpc.discovery.search.useQuery({ query }, { enabled: query.trim().length > 1 }); return <div className="flex min-h-0 flex-1 flex-col bg-background"><header className="flex items-center gap-3 border-b border-border/70 px-4 py-3 sm:px-8 sm:py-4"><button onClick={onBack} className="rounded-full p-2 hover:bg-muted"><ArrowLeft className="h-5 w-5" /></button><div><p className="text-xl font-bold">New message</p><p className="text-[11px] text-muted-foreground">Search by name or username</p></div></header><main className="mx-auto w-full max-w-2xl flex-1 p-4 sm:p-8"><div className="relative"><Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-muted-foreground" /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Who do you want to message?" className="h-14 w-full rounded-2xl border border-border bg-card pl-12 pr-4 text-sm outline-none shadow-sm" /></div>{query.trim().length < 2 ? <div className="mt-16 text-center text-sm text-muted-foreground"><Users className="mx-auto mb-3 h-7 w-7" /><p>Type at least two characters to find a person.</p></div> : <div className="mt-5 space-y-2">{(results.data?.users ?? []).map((peer: any) => <button key={peer.id} onClick={() => onSelect(peer)} className="flex w-full items-center gap-3 rounded-2xl border border-border/70 bg-card p-3 text-left transition hover:border-violet-300"><Avatar user={peer} online={isOnline(peer)} /><span className="min-w-0 flex-1"><b className="block truncate text-sm">{displayName(peer)}</b><span className="text-xs text-muted-foreground">@{peer.username || "user"}</span></span><ChevronDown className="h-4 w-4 -rotate-90 text-muted-foreground" /></button>)}{!results.data?.users?.length && !results.isLoading && <p className="p-8 text-center text-sm text-muted-foreground">No people found.</p>}</div>}</main></div>; }

export function AdvancedMessengerChat({ peer, otherUserId, initialCall, onBack }: { peer?: any; otherUserId?: number; initialCall?: { id: number; type: "audio" | "video"; caller: boolean }; onBack?: () => void }) {
  const { user } = useAuth(); const resolvedPeer = peer || { id: otherUserId, name: `User #${otherUserId}` }; const peerId = Number(resolvedPeer.id); const threadQuery = trpc.messages.list.useQuery({ otherUserId: peerId }, { enabled: Boolean(user && peerId), refetchInterval: 1200 }); const callsQuery = trpc.messages.calls.useQuery({ otherUserId: peerId }, { enabled: Boolean(user && peerId), refetchInterval: 1200 }); const typingQuery = trpc.messages.typingGet.useQuery({ peerId }, { enabled: Boolean(user && peerId), refetchInterval: 900 }); const settingsQuery = trpc.messages.settingsGet.useQuery({ peerId }, { enabled: Boolean(user && peerId) }); const send = trpc.messages.send.useMutation({ onSuccess: () => threadQuery.refetch(), onError: (error) => toast.error("Message failed", { description: error.message }) }); const read = trpc.messages.read.useMutation(); const setTyping = trpc.messages.typingSet.useMutation(); const react = trpc.messages.react.useMutation({ onSuccess: () => threadQuery.refetch() }); const remove = trpc.messages.delete.useMutation({ onSuccess: () => threadQuery.refetch() }); const forward = trpc.messages.forward.useMutation({ onSuccess: () => toast.success("Message forwarded") }); const startCall = trpc.messages.startCall.useMutation(); const updateCall = trpc.messages.updateCall.useMutation(); const upload = trpc.media.uploadBase64.useMutation(); const [draft, setDraft] = useState(""); const [replyTo, setReplyTo] = useState<any>(null); const [pressedMessage, setPressedMessage] = useState<number | null>(null); const [searchOpen, setSearchOpen] = useState(false); const [messageSearch, setMessageSearch] = useState(""); const [menuOpen, setMenuOpen] = useState(false); const [forwardMessage, setForwardMessage] = useState<any>(null); const [fullscreenMedia, setFullscreenMedia] = useState<string | null>(null); const [pendingFiles, setPendingFiles] = useState<File[]>([]); const [call, setCall] = useState<{ id: number; type: "audio" | "video"; caller: boolean } | null>(initialCall || null); const [recording, setRecording] = useState(false); const [recordingMs, setRecordingMs] = useState(0); const [cancelRecording, setCancelRecording] = useState(false); const [offlineQueue, setOfflineQueue] = usePersistedQueue(peerId); const recordStartX = useRef<number | null>(null); const recorder = useRef<MediaRecorder | null>(null); const chunks = useRef<Blob[]>([]); const fileInput = useRef<HTMLInputElement>(null); const cameraInput = useRef<HTMLInputElement>(null); const scrollRef = useRef<HTMLDivElement>(null); const incoming = callsQuery.data?.find((item: any) => item.callerId !== user?.id && item.receiverId === user?.id && item.status === "pending"); const messages = (threadQuery.data ?? []).filter((item: any) => !messageSearch.trim() || item.content.toLowerCase().includes(messageSearch.toLowerCase())); const firstUnreadId = messages.find((item: any) => item.receiverId === user?.id && !item.isRead)?.id; const lastReadId = [...messages].reverse().find((item: any) => item.senderId === user?.id && item.isRead)?.id; const typing = (typingQuery.data ?? []).some((entry: any) => entry.user?.id === peerId);
  useEffect(() => { read.mutate({ otherUserId: peerId }); }, [peerId]); useEffect(() => { scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "instant" as ScrollBehavior }); }, [threadQuery.data?.length, peerId]); useEffect(() => { const flush = () => { if (!navigator.onLine || !offlineQueue.length) return; const pending = [...offlineQueue]; setOfflineQueue([]); pending.forEach((item) => send.mutate({ receiverId: peerId, content: item.content, replyToId: item.replyToId })); }; window.addEventListener("online", flush); flush(); return () => window.removeEventListener("online", flush); }, [peerId, offlineQueue.length]); useEffect(() => { if (!recording) return; const timer = window.setInterval(() => setRecordingMs((value) => value + 100), 100); return () => window.clearInterval(timer); }, [recording]);
  const sendText = () => { const content = draft.trim(); if (!content) return; if (!navigator.onLine) { setOfflineQueue((queue) => [...queue, { id: crypto.randomUUID(), content, replyToId: replyTo?.id, createdAt: Date.now() }]); setDraft(""); setReplyTo(null); toast("You're offline. Messages will send when reconnected."); return; } send.mutate({ receiverId: peerId, content, replyToId: replyTo?.id }); setDraft(""); setReplyTo(null); }; const type = (value: string) => { setDraft(value); if (value.trim()) setTyping.mutate({ peerId }); }; const beginCall = async (type: "audio" | "video") => { if (callsQuery.data?.some((item: any) => item.status === "pending" || item.status === "accepted")) { toast.error("This chat already has an active call."); return; } try { const id = await startCall.mutateAsync({ receiverId: peerId, callType: type }); if (id) setCall({ id: Number(id), type, caller: true }); } catch (error: any) { toast.error("Could not start call", { description: error.message }); } }; const acceptIncoming = async () => { if (!incoming) return; await updateCall.mutateAsync({ callId: incoming.id, status: "accepted" }); setCall({ id: incoming.id, type: incoming.callType, caller: false }); }; const declineIncoming = async () => { if (incoming) await updateCall.mutateAsync({ callId: incoming.id, status: "declined" }); callsQuery.refetch(); }; const confirmFiles = async () => { const files = pendingFiles.slice(0, 10); if (!files.length) return; setPendingFiles([]); try { await Promise.all(files.map(async (file) => { const reader = new FileReader(); const data = await new Promise<string>((resolve, reject) => { reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); }); const uploaded = await upload.mutateAsync({ fileName: file.name, base64Data: data, contentType: file.type || "image/jpeg" }); await send.mutateAsync({ receiverId: peerId, content: `MEDIA:${uploaded.url}` }); })); toast.success(`${files.length} photo${files.length === 1 ? "" : "s"} sent`); } catch (error: any) { toast.error("Could not send photo", { description: error.message }); } }; const selectFiles = (files: FileList | null) => { if (files?.length) setPendingFiles(Array.from(files).slice(0, 10)); }; const startRecording = async () => { if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") { toast.error("Voice notes need microphone access in a supported browser."); return; } try { const stream = await navigator.mediaDevices.getUserMedia({ audio: true }); const mediaRecorder = new MediaRecorder(stream); chunks.current = []; mediaRecorder.ondataavailable = (event) => chunks.current.push(event.data); mediaRecorder.onstop = async () => { stream.getTracks().forEach((track) => track.stop()); if (cancelRecording) return; const blob = new Blob(chunks.current, { type: "audio/webm" }); const reader = new FileReader(); const data = await new Promise<string>((resolve, reject) => { reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(blob); }); const audio = await upload.mutateAsync({ fileName: `voice-${Date.now()}.webm`, base64Data: data, contentType: "audio/webm" }); await send.mutateAsync({ receiverId: peerId, content: "Voice note", audioUrl: audio.url, replyToId: replyTo?.id }); setReplyTo(null); }; recorder.current = mediaRecorder; mediaRecorder.start(); setRecording(true); setRecordingMs(0); setCancelRecording(false); } catch (error: any) { toast.error("Microphone permission is required", { description: error.message }); } }; const stopRecording = (cancel = false) => { if (!recorder.current) return; setCancelRecording(cancel); recorder.current.stop(); recorder.current = null; setRecording(false); setRecordingMs(0); }; const exportChat = () => { const content = messages.map((item: any) => `[${new Date(item.createdAt).toLocaleString()}] ${item.senderId === user?.id ? "You" : displayName(resolvedPeer)}: ${item.audioUrl ? "Voice note" : item.content}`).join("\n"); const blob = new Blob([content || "No messages yet."], { type: "text/plain;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `tanryugram-${displayName(resolvedPeer).replace(/\s+/g, "-").toLowerCase()}.txt`; anchor.click(); URL.revokeObjectURL(url); toast.success("Chat exported"); };
  return <div className="relative flex min-h-0 flex-1 flex-col bg-card">{call && <CallOverlay callId={call.id} callType={call.type} isCaller={call.caller} peer={resolvedPeer} onClose={() => { setCall(null); callsQuery.refetch(); }} onCallAgain={() => { void beginCall(call.type); }} />}{incoming && !call && <IncomingCallScreen caller={resolvedPeer} callType={incoming.callType} onAccept={acceptIncoming} onDecline={declineIncoming} />}{forwardMessage && <ForwardDrawer message={forwardMessage} onClose={() => setForwardMessage(null)} onForward={(receiverIds) => { forward.mutate({ messageIds: [forwardMessage.id], receiverIds }); setForwardMessage(null); }} />}{fullscreenMedia && <div className="fixed inset-0 z-[95] flex items-center justify-center bg-black/90 p-4" onClick={() => setFullscreenMedia(null)}><button onClick={() => setFullscreenMedia(null)} className="absolute right-4 top-4 rounded-full bg-white/10 p-3 text-white"><X className="h-5 w-5" /></button><img src={fullscreenMedia} alt="Fullscreen shared photo" className="max-h-full max-w-full rounded-xl object-contain" /></div>}<header className="flex items-center gap-3 border-b border-border/70 px-3 py-3 sm:px-6 sm:py-4"><button onClick={onBack} aria-label="Back to inbox" className="rounded-full p-2 hover:bg-muted"><ArrowLeft className="h-5 w-5" /></button><Avatar user={resolvedPeer} online={isOnline(resolvedPeer)} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{displayName(resolvedPeer, `User #${peerId}`)}</p><p className={`flex items-center gap-1.5 text-[11px] ${isOnline(resolvedPeer) ? "text-emerald-500" : "text-muted-foreground"}`}><span className={`h-1.5 w-1.5 rounded-full ${isOnline(resolvedPeer) ? "bg-emerald-500" : "bg-zinc-400"}`} />{isOnline(resolvedPeer) ? "Active now" : "Offline"}</p></div><button onClick={() => beginCall("audio")} aria-label="Start audio call" className="rounded-xl p-2.5 text-muted-foreground hover:bg-muted"><Phone className="h-5 w-5" /></button><button onClick={() => beginCall("video")} aria-label="Start video call" className="rounded-xl p-2.5 text-muted-foreground hover:bg-muted"><Video className="h-5 w-5" /></button><button onClick={() => setSearchOpen((value) => !value)} aria-label="Search conversation" className="rounded-xl p-2.5 text-muted-foreground hover:bg-muted"><Search className="h-5 w-5" /></button><button onClick={exportChat} aria-label="Export chat" className="hidden rounded-xl p-2.5 text-muted-foreground hover:bg-muted sm:block"><Download className="h-5 w-5" /></button><button onClick={() => setMenuOpen((value) => !value)} aria-label="Chat settings" className="rounded-xl p-2.5 text-muted-foreground hover:bg-muted"><MoreHorizontal className="h-5 w-5" /></button>{menuOpen && <ChatMenu peerId={peerId} muted={settingsQuery.data?.isMuted} pinned={settingsQuery.data?.isPinned} onClose={() => setMenuOpen(false)} onSearch={() => { setSearchOpen(true); setMenuOpen(false); }} onExport={exportChat} />}</header>{pendingFiles.length > 0 && <div className="border-b border-border/70 bg-violet-500/5 p-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold">Preview {pendingFiles.length} photo{pendingFiles.length === 1 ? "" : "s"}</p><button onClick={() => setPendingFiles([])} className="rounded-full p-1.5 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div><div className="mt-2 flex gap-2 overflow-x-auto">{pendingFiles.map((file) => <PendingImagePreview key={`${file.name}-${file.size}`} file={file} />)}</div><button disabled={upload.isPending || send.isPending} onClick={() => void confirmFiles()} className="mt-3 w-full rounded-xl bg-foreground py-2.5 text-xs font-semibold text-background disabled:opacity-50">{upload.isPending || send.isPending ? "Sending photos…" : "Send photos"}</button></div>}{searchOpen && <div className="border-b border-border/70 p-3"><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input autoFocus value={messageSearch} onChange={(event) => setMessageSearch(event.target.value)} placeholder="Search in this conversation" className="h-10 w-full rounded-xl bg-muted pl-9 pr-3 text-xs outline-none" /></div></div>}{callsQuery.data?.length ? <div className="border-b border-border/70 px-4 py-2"><div className="flex gap-2 overflow-x-auto">{callsQuery.data.slice(0, 5).map((item: any) => <span key={item.id} className={`whitespace-nowrap rounded-full px-2.5 py-1 text-[10px] ${item.status === "missed" ? "bg-rose-500/10 text-rose-500" : "bg-muted text-muted-foreground"}`}>{item.callType === "video" ? "Video" : "Audio"} · {item.status} · {item.durationSeconds ? `${item.durationSeconds}s` : "—"}</span>)}</div></div> : null}<div ref={scrollRef} className="min-h-0 flex-1 space-y-3 overflow-y-auto p-4 sm:p-6">{messages.map((item: any, index: number) => <React.Fragment key={item.id}>{item.id === firstUnreadId && <div className="my-4 flex items-center gap-3 text-[10px] font-semibold text-violet-500"><span className="h-px flex-1 bg-violet-500/30" /><span>New messages</span><span className="h-px flex-1 bg-violet-500/30" /></div>}{(index === 0 || dateLabel(messages[index - 1].createdAt) !== dateLabel(item.createdAt)) && <div className="my-5 text-center text-[10px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">{dateLabel(item.createdAt)}</div>}<MessageBubble item={item} mine={item.senderId === user?.id} pressed={pressedMessage === item.id} onOpenMedia={setFullscreenMedia} onPress={() => setPressedMessage(item.id)} onReply={() => { setReplyTo(item); setPressedMessage(null); }} onReact={(emoji) => { react.mutate({ messageId: item.id, emoji }); setPressedMessage(null); }} onDelete={(everyone) => { remove.mutate({ messageId: item.id, everyone }); setPressedMessage(null); }} onForward={() => { setForwardMessage(item); setPressedMessage(null); }} showSeen={item.id === lastReadId} /></React.Fragment>)}{offlineQueue.map((item) => <div key={item.id} className="flex justify-end"><div className="max-w-[80%] rounded-[20px] rounded-br-md border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm"><p>{item.content}</p><p className="mt-1 text-[10px] text-amber-600">Queued while offline · will retry automatically</p></div></div>)}{typing && <div className="flex items-center gap-2 text-xs text-muted-foreground"><span className="rounded-2xl bg-muted px-3 py-2">typing<span className="inline-flex w-5 overflow-hidden"><span className="animate-pulse">...</span></span></span></div>}{!messages.length && !offlineQueue.length && <div className="flex h-full items-center justify-center text-center text-sm text-muted-foreground"><div><p className="font-semibold text-foreground">Start a conversation</p><p className="mt-1">Send a message, photo, or voice note.</p></div></div>}</div><div className="border-t border-border/70 p-3 sm:p-4">{replyTo && <div className="mb-2 flex items-center gap-2 rounded-xl border-l-2 border-violet-500 bg-violet-500/10 px-3 py-2 text-xs"><Reply className="h-3.5 w-3.5 text-violet-500" /><span className="min-w-0 flex-1 truncate">Replying to: {replyTo.content}</span><button onClick={() => setReplyTo(null)}><X className="h-3.5 w-3.5" /></button></div>}{recording && <div className="mb-2 flex items-center gap-3 rounded-xl bg-rose-500/10 px-3 py-2 text-xs text-rose-500"><span className="h-2 w-2 animate-pulse rounded-full bg-current" /><span className="font-semibold tabular-nums">{(recordingMs / 1000).toFixed(1)}s</span><span className="flex-1">{cancelRecording ? "Release to cancel" : "Slide left to cancel"}</span></div>}<div className="flex items-center gap-1.5 rounded-2xl bg-muted p-1.5"><button onClick={() => cameraInput.current?.click()} className="rounded-xl p-2.5 text-muted-foreground hover:bg-card" aria-label="Open camera"><Camera className="h-4 w-4" /></button><button onClick={() => fileInput.current?.click()} className="rounded-xl p-2.5 text-muted-foreground hover:bg-card" aria-label="Attach image"><Paperclip className="h-4 w-4" /></button><input ref={cameraInput} type="file" accept="image/*" capture="environment" className="hidden" onChange={(event) => { selectFiles(event.target.files); event.currentTarget.value = ""; }} /><input ref={fileInput} type="file" accept="image/*" multiple className="hidden" onChange={(event) => { selectFiles(event.target.files); event.currentTarget.value = ""; }} /><input value={draft} onChange={(event) => type(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); sendText(); } }} placeholder="Write a message..." className="min-w-0 flex-1 bg-transparent px-2 text-sm outline-none placeholder:text-muted-foreground" />{draft.trim() ? <button onClick={sendText} className="rounded-xl bg-foreground p-2.5 text-background transition active:scale-95"><Send className="h-4 w-4" /></button> : <button onPointerDown={(event) => { recordStartX.current = event.clientX; void startRecording(); }} onPointerMove={(event) => { if (recordStartX.current !== null) setCancelRecording(event.clientX < recordStartX.current - 70); }} onPointerUp={() => stopRecording(cancelRecording)} onPointerCancel={() => stopRecording(true)} className="rounded-xl bg-foreground p-2.5 text-background transition active:scale-95" aria-label="Hold to record voice note"><Mic className="h-4 w-4" /></button>}</div></div></div>;
}

function GroupPollCard({ pollId }: { pollId: number }) {
  const pollQuery = trpc.messages.poll.useQuery({ pollId }, { refetchInterval: 2500 }); const vote = trpc.messages.votePoll.useMutation({ onSuccess: () => pollQuery.refetch(), onError: (error) => toast.error("Could not vote", { description: error.message }) }); const data = pollQuery.data; if (!data) return <div className="rounded-2xl bg-violet-500/10 p-3 text-xs">Loading poll…</div>; const closed = Boolean(data.poll.closesAt && new Date(data.poll.closesAt).getTime() <= Date.now()); const max = Math.max(1, ...data.options.map((option: any) => option.votes)); return <div className="w-full rounded-2xl border border-violet-500/20 bg-violet-500/5 p-3 text-foreground"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-violet-500">Group poll {closed && "· Closed"}</p><p className="mt-1 text-sm font-semibold">{data.poll.question}</p><div className="mt-3 space-y-2">{data.options.map((option: any) => <button key={option.id} disabled={closed || vote.isPending} onClick={() => vote.mutate({ pollId, optionId: option.id })} className={`relative w-full overflow-hidden rounded-xl border px-3 py-2 text-left text-xs ${option.voted ? "border-violet-500 bg-violet-500/10" : "border-border bg-card"}`}><span className="absolute inset-y-0 left-0 bg-violet-500/10" style={{ width: `${(option.votes / max) * 100}%` }} /><span className="relative flex justify-between gap-3"><span>{option.label}</span><span>{option.votes} vote{option.votes === 1 ? "" : "s"}</span></span></button>)}</div><p className="mt-2 text-[10px] text-muted-foreground">{data.totalVotes} total voters · {data.poll.allowsMultiple ? "Multiple answers allowed" : "Tap to change your vote"}</p></div>;
}

function GroupEventCard({ event }: { event: any }) {
  const { user } = useAuth();
  const eventsQuery = trpc.messages.events.useQuery({ groupId: event.groupId }, { refetchInterval: 4000 });
  const liveEvent = (eventsQuery.data ?? []).find((candidate: any) => candidate.id === event.id) ?? event;
  const rsvp = trpc.messages.rsvpEvent.useMutation({ onSuccess: () => eventsQuery.refetch(), onError: (error) => toast.error("Could not update RSVP", { description: error.message }) });
  const attendees = liveEvent.attendees ?? []; const counts = liveEvent.attendeeCounts ?? { going: 0, maybe: 0, cant_go: 0 }; const myRsvp = attendees.find((attendee: any) => attendee.user.id === user?.id)?.rsvp.status;
  const attending = attendees.filter((attendee: any) => attendee.rsvp.status !== "cant_go"); const attendeeNames = attending.slice(0, 4).map((attendee: any) => displayName(attendee.user));
  const calendar = `BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nSUMMARY:${liveEvent.name}\nDTSTART:${new Date(liveEvent.startsAt).toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "")}\nLOCATION:${liveEvent.location || ""}\nDESCRIPTION:${liveEvent.description || ""}\nEND:VEVENT\nEND:VCALENDAR`;
  const download = () => { const url = URL.createObjectURL(new Blob([calendar], { type: "text/calendar" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${liveEvent.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}.ics`; anchor.click(); URL.revokeObjectURL(url); };
  return <div className="w-full rounded-2xl border border-sky-500/20 bg-sky-500/5 p-3 text-foreground"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-sky-600">Group event</p><p className="mt-1 text-sm font-semibold">{liveEvent.name}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(liveEvent.startsAt).toLocaleString()} {liveEvent.location ? `· ${liveEvent.location}` : ""}</p>{liveEvent.description && <p className="mt-2 text-xs">{liveEvent.description}</p>}<div className="mt-2 rounded-xl bg-card/70 px-2.5 py-2 text-[10px] text-muted-foreground"><p><b className="text-foreground">{counts.going} going</b>{counts.maybe ? ` · ${counts.maybe} maybe` : ""}</p><p className="mt-0.5 truncate">{attendeeNames.length ? `Attending: ${attendeeNames.join(", ")}${attending.length > attendeeNames.length ? " and others" : ""}` : "Be the first to RSVP"}</p></div><div className="mt-3 flex flex-wrap gap-1.5"><button onClick={() => rsvp.mutate({ eventId: liveEvent.id, status: "going" })} className={`rounded-lg px-2 py-1 text-[10px] font-semibold text-emerald-600 ${myRsvp === "going" ? "bg-emerald-500/20 ring-1 ring-emerald-500/40" : "bg-emerald-500/10"}`}>Going</button><button onClick={() => rsvp.mutate({ eventId: liveEvent.id, status: "maybe" })} className={`rounded-lg px-2 py-1 text-[10px] font-semibold text-amber-600 ${myRsvp === "maybe" ? "bg-amber-500/20 ring-1 ring-amber-500/40" : "bg-amber-500/10"}`}>Maybe</button><button onClick={() => rsvp.mutate({ eventId: liveEvent.id, status: "cant_go" })} className={`rounded-lg px-2 py-1 text-[10px] font-semibold text-rose-600 ${myRsvp === "cant_go" ? "bg-rose-500/20 ring-1 ring-rose-500/40" : "bg-rose-500/10"}`}>Can’t go</button><button onClick={download} className="rounded-lg bg-muted px-2 py-1 text-[10px] font-semibold">Add to calendar</button></div></div>;
}

